mod solution;

fn main() {
    let cases = [
    (r#"[1,2,1,3,2,4]"#, r#"3,4,4"#),
    (r#"[1,1,1,1,1,1]"#, r#"1,1,1"#),
    (r#"
[1,1,1,1,1,1]
"#, r#"1,1,1"#),
    (r#"  
[1,2,1,3,2,4]
  "#, r#"3,4,4"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS mo-algorithm");
}
